/* Compact price-range control, combined with existing catalog filters. */
(()=>{
 if(location.pathname.startsWith('/cms')||window.__rentcamPriceFilter)return;window.__rentcamPriceFilter=true;
 const money=n=>'Rp'+Number(n).toLocaleString('id-ID'),range=()=>{const u=new URLSearchParams(location.search),read=k=>{const v=u.get(k);return v!==null&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null};return {min:read('minPrice'),max:read('maxPrice')}};
 const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="3"/><circle cx="12" cy="12" r="3"/><path d="M6 10v4M18 10v4"/></svg>';
 const style=document.createElement('style');style.textContent=`#app .catalog-filter-row{display:flex!important;align-items:flex-end!important;gap:12px!important;flex-wrap:nowrap!important}#app .catalog-filter-row .catalog-filter-field{flex:1;min-width:0}.rc-price-filter-icon{width:46px;height:46px;flex:0 0 46px;display:grid;place-items:center;border:1px solid #ddd;border-radius:11px;background:#fff;color:#111;cursor:pointer;position:relative}#app button.rc-price-filter-icon .rc-control-label{display:none!important}#app button.rc-price-filter-icon{display:grid!important;place-items:center!important;padding:0!important;min-width:46px;min-height:46px;box-sizing:border-box}#app button.rc-price-filter-icon svg{width:23px;height:23px;display:block;flex:none}.rc-price-filter-icon[data-active=true]::after{content:'';position:absolute;top:7px;right:7px;width:6px;height:6px;border-radius:50%;background:#111}#app [data-price-hidden=true]{display:none!important}.rc-price-empty{text-align:center;padding:35px 16px;font-size:13px;color:#777}#rcPriceFilterDialog{width:min(440px,calc(100% - 24px));max-height:85dvh;box-sizing:border-box;overflow:auto;padding:24px;border:1px solid #ddd;border-radius:18px;background:#fff;color:#111;font-family:inherit}#rcPriceFilterDialog::backdrop{background:#0008}.rc-price-heading{display:flex;justify-content:space-between;gap:16px}.rc-price-heading h2{font-size:20px;margin:0}.rc-price-heading button{border:1px solid #ddd;border-radius:8px;background:#fff;padding:5px 10px;font-size:20px;cursor:pointer}#rcPriceFilterDialog p{font-size:12px;color:#777;line-height:1.7}.rc-price-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.rc-price-fields label{font-size:12px;font-weight:650}.rc-price-fields input{display:block;width:100%;box-sizing:border-box;min-width:0;margin-top:8px;padding:12px;border:1px solid #ddd;border-radius:9px;font:inherit;font-size:14px}.rc-price-presets{display:flex;flex-wrap:wrap;gap:8px}.rc-price-presets button{border:1px solid #ddd;border-radius:8px;padding:9px 11px;background:#fff;font-size:11px;cursor:pointer}.rc-price-actions{display:flex;gap:12px;margin-top:22px}.rc-price-actions button{flex:1;border:1px solid #ddd;border-radius:10px;padding:12px;font-size:12px;cursor:pointer;background:#fff}.rc-price-actions button[type=submit]{background:#111;color:#fff;border-color:#111}html[data-store-theme=black] .rc-price-filter-icon{background:#24252a;color:#eee;border-color:#38393d}html[data-store-theme=black] .rc-price-filter-icon[data-active=true]::after{background:#fff}`;document.head.append(style);
 const dialog=document.createElement('dialog');dialog.id='rcPriceFilterDialog';dialog.setAttribute('aria-labelledby','rcPriceFilterTitle');dialog.innerHTML=`<div class="rc-price-heading"><h2 id="rcPriceFilterTitle">Rentang Harga</h2><button type="button" data-price-close aria-label="Tutup rentang harga">×</button></div><p>Harga sewa per hari dalam Rupiah. Pilih rentang sesuai anggaran Anda.</p><form><div class="rc-price-fields"><label>Harga minimum (Rp)<input name="min" type="text" inputmode="numeric" autocomplete="off" placeholder="0"></label><label>Harga maksimum (Rp)<input name="max" type="text" inputmode="numeric" autocomplete="off" placeholder="Tanpa batas"></label></div><div class="rc-price-presets"><button type="button" data-price-preset="0,250000">≤ Rp250.000</button><button type="button" data-price-preset="250000,1000000">Rp250.000 – Rp1.000.000</button><button type="button" data-price-preset="1000000,">≥ Rp1.000.000</button></div><p data-price-error role="alert" hidden></p><div class="rc-price-actions"><button type="button" data-price-reset>Reset</button><button type="submit">Lihat produk</button></div></form>`;document.body.append(dialog);const form=dialog.querySelector('form');
 const digits=v=>String(v??'').replace(/[^0-9]/g,'').slice(0,15),formatted=v=>{const n=digits(v);return n===''?'':Number(n).toLocaleString('id-ID')};
 form.addEventListener('input',e=>{const input=e.target;if(!['min','max'].includes(input.name))return;const before=input.value.slice(0,input.selectionStart).replace(/[^0-9]/g,'').length;input.value=formatted(input.value);let seen=0,caret=0;for(;caret<input.value.length&&seen<before;caret++)if(/[0-9]/.test(input.value[caret]))seen++;input.setSelectionRange(caret,caret)});
 function setRange(min,max){const u=new URLSearchParams(location.search);for(const [k,v] of [['minPrice',min],['maxPrice',max]])if(v===null||v==='')u.delete(k);else u.set(k,String(v));history.replaceState({},'',location.pathname+(u.size?'?'+u:''));apply()}
 dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-price-close'))dialog.close();if(b.hasAttribute('data-price-reset')){setRange(null,null);dialog.close()}if(b.dataset.pricePreset){const [min,max]=b.dataset.pricePreset.split(',');form.elements.min.value=formatted(min);form.elements.max.value=formatted(max)}});
 form.addEventListener('submit',e=>{e.preventDefault();const min=digits(form.elements.min.value),max=digits(form.elements.max.value),error=form.querySelector('[data-price-error]');if(min!==''&&max!==''&&Number(min)>Number(max)){error.textContent='Harga maksimum harus sama atau lebih besar dari harga minimum.';error.hidden=false;return}error.hidden=true;setRange(min,max);dialog.close()});
 document.addEventListener('click',e=>{if(!e.target.closest('[data-price-filter]'))return;const {min,max}=range();form.elements.min.value=formatted(min);form.elements.max.value=formatted(max);form.querySelector('[data-price-error]').hidden=true;dialog.showModal()});
 function apply(){if(location.pathname!=='/produk')return;const row=document.querySelector('#app .catalog-filter-row');if(!row)return;let button=row.querySelector('[data-price-filter]');if(!button){button=document.createElement('button');button.type='button';button.className='rc-price-filter-icon';button.dataset.priceFilter='';button.setAttribute('aria-label','Rentang Harga');button.setAttribute('aria-haspopup','dialog');button.innerHTML=icon;row.append(button)}const {min,max}=range(),active=min!==null||max!==null;button.dataset.active=String(active);button.title=active?'Rentang Harga: '+(min===null?'Rp0':money(min))+' – '+(max===null?'tanpa batas':money(max)):'Rentang Harga';
 const results=document.getElementById('catalogResults');if(!results)return;const cards=[...results.querySelectorAll('.pcard')];let count=0;for(const card of cards){const priceText=card.querySelector('.price')?.textContent||'',matches=[...priceText.matchAll(/Rp\s*([\d.,]+)/g)],price=matches.length?Number(matches.at(-1)[1].replace(/[.,]/g,'')):null,show=price===null||((min===null||price>=min)&&(max===null||price<=max));card.dataset.priceHidden=String(!show);if(show)count++}for(const group of results.querySelectorAll('.catalog-group')){const n=group.querySelectorAll('.pcard[data-price-hidden=false]').length;group.dataset.priceHidden=String(!n);const label=group.querySelector('header>span');if(label&&label.textContent!==n+' produk')label.textContent=n+' produk'}const label=document.getElementById('catalogResultCount');if(label){const text=label.textContent.replace(/^\d+/,String(count));if(label.textContent!==text)label.textContent=text}let empty=results.querySelector('.rc-price-empty');if(active&&cards.length&&!count){if(!empty){empty=document.createElement('p');empty.className='rc-price-empty';empty.textContent='Tidak ada produk dalam rentang harga ini. Ubah atau reset rentang harga.';results.append(empty)}}else empty?.remove();
 }
 let pending=false;function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;apply()})}new MutationObserver(schedule).observe(document.getElementById('app')||document.body,{childList:true,subtree:true});document.addEventListener('rentcam-route-change',schedule);document.addEventListener('rentcam-cms-updated',schedule);addEventListener('popstate',schedule);schedule();
})();
